PRAGMA foreign_keys = ON;
CREATE TABLE sectors (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name_en TEXT NOT NULL, name_ar TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE profiles (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')), published_at TEXT, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, name_en TEXT NOT NULL DEFAULT '', name_ar TEXT NOT NULL DEFAULT '', title_en TEXT NOT NULL DEFAULT '', title_ar TEXT NOT NULL DEFAULT '', org_en TEXT NOT NULL DEFAULT '', org_ar TEXT NOT NULL DEFAULT '', summary_en TEXT NOT NULL DEFAULT '', summary_ar TEXT NOT NULL DEFAULT '', body_en TEXT NOT NULL DEFAULT '', body_ar TEXT NOT NULL DEFAULT '', pull_quote_en TEXT NOT NULL DEFAULT '', pull_quote_ar TEXT NOT NULL DEFAULT '', sector_id INTEGER REFERENCES sectors(id), city TEXT NOT NULL DEFAULT '', photo_key TEXT, photo_alt_en TEXT NOT NULL DEFAULT '', photo_alt_ar TEXT NOT NULL DEFAULT '', linkedin_url TEXT NOT NULL DEFAULT '', x_url TEXT NOT NULL DEFAULT '', instagram_url TEXT NOT NULL DEFAULT '', facebook_url TEXT NOT NULL DEFAULT '', website_url TEXT NOT NULL DEFAULT '', org_linkedin_url TEXT NOT NULL DEFAULT '', featured INTEGER NOT NULL DEFAULT 0 CHECK(featured IN (0,1)), consent_confirmed INTEGER NOT NULL DEFAULT 0 CHECK(consent_confirmed IN (0,1)), consent_note TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT);
CREATE INDEX idx_profiles_status ON profiles(status,published_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX idx_profiles_sector ON profiles(sector_id,status) WHERE deleted_at IS NULL;
CREATE INDEX idx_profiles_updated ON profiles(updated_at DESC) WHERE deleted_at IS NULL;
CREATE TABLE audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_email TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, details_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_audit_created ON audit_log(created_at DESC);
CREATE TABLE contact_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE takedown_requests (id INTEGER PRIMARY KEY AUTOINCREMENT, profile_slug TEXT NOT NULL, requester_email TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE site_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
